-- Create database separately: CREATE DATABASE movie_streaming;
-- Connect to movie_streaming, then execute this file.
CREATE TABLE users(user_id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,full_name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE subscription_plans(plan_id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,plan_name VARCHAR(50) NOT NULL UNIQUE,price NUMERIC(8,2) NOT NULL,duration_days INT NOT NULL,description VARCHAR(255));
CREATE TABLE payments(payment_id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,user_id INT NOT NULL REFERENCES users(user_id),plan_id INT NOT NULL REFERENCES subscription_plans(plan_id),amount NUMERIC(8,2) NOT NULL,payment_status VARCHAR(20) DEFAULT 'SIMULATED',payment_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE genres(genre_id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,genre_name VARCHAR(60) NOT NULL UNIQUE);
CREATE TABLE movies(movie_id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,title VARCHAR(180) NOT NULL,description TEXT,release_year INT,language VARCHAR(60),rating NUMERIC(3,1) DEFAULT 0,genre_id INT REFERENCES genres(genre_id));
CREATE TABLE series(series_id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,title VARCHAR(180) NOT NULL,description TEXT,release_year INT,language VARCHAR(60),rating NUMERIC(3,1) DEFAULT 0,genre_id INT REFERENCES genres(genre_id));
CREATE TABLE seasons(season_id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,series_id INT NOT NULL REFERENCES series(series_id),season_number INT NOT NULL,title VARCHAR(120),UNIQUE(series_id,season_number));
CREATE TABLE episodes(episode_id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,season_id INT NOT NULL REFERENCES seasons(season_id),episode_number INT NOT NULL,title VARCHAR(180) NOT NULL,duration_minutes INT,description TEXT,UNIQUE(season_id,episode_number));
CREATE TABLE actors(actor_id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,actor_name VARCHAR(120) NOT NULL);
CREATE TABLE casting(casting_id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,actor_id INT NOT NULL REFERENCES actors(actor_id),movie_id INT REFERENCES movies(movie_id),episode_id INT REFERENCES episodes(episode_id),role_name VARCHAR(100),CHECK((movie_id IS NOT NULL AND episode_id IS NULL) OR (movie_id IS NULL AND episode_id IS NOT NULL)));
CREATE TABLE reviews(review_id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,user_id INT NOT NULL REFERENCES users(user_id),movie_id INT REFERENCES movies(movie_id),series_id INT REFERENCES series(series_id),episode_id INT REFERENCES episodes(episode_id),review_text TEXT NOT NULL,rating INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CHECK(num_nonnulls(movie_id,series_id,episode_id)=1),CHECK(rating BETWEEN 1 AND 5));
CREATE TABLE watchlists(watchlist_id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,user_id INT NOT NULL REFERENCES users(user_id),movie_id INT REFERENCES movies(movie_id),series_id INT REFERENCES series(series_id),added_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CHECK((movie_id IS NOT NULL AND series_id IS NULL) OR (movie_id IS NULL AND series_id IS NOT NULL)));
